const preferenceKey='poppy-workspace-v2';
export function readWorkspacePreferences(storage){try{const value=JSON.parse(storage?.getItem(preferenceKey)||'null');return {guided:typeof value?.guided==='boolean'?value.guided:true,inspectorOpen:typeof value?.inspectorOpen==='boolean'?value.inspectorOpen:false};}catch{return {guided:true,inspectorOpen:false};}}
function storage(){try{return localStorage;}catch{return null;}}
function persist(a){try{storage()?.setItem(preferenceKey,JSON.stringify({guided:!!a.workspaceGuided,inspectorOpen:!!a.propertiesOpen}));}catch{}}
export function initWorkspace(a){if(a.workspaceInitialized)return;a.workspaceInitialized=true;if(a.workspaceGuided===undefined){const prefs=readWorkspacePreferences(storage());a.workspaceGuided=prefs.guided;a.propertiesOpen=prefs.inspectorOpen;}a.showScaffold=true;syncWorkspace(a);}
export function syncWorkspace(a){const root=document.documentElement;if(root)root.dataset.workspace=a.workspaceGuided?'guided':'detailed';const inspector=document.querySelector('.inspector');if(inspector)inspector.classList.toggle('open',!!a.propertiesOpen);for(const button of document.querySelectorAll('[data-properties],#show-inspector')){button.setAttribute('aria-expanded',!!a.propertiesOpen);button.setAttribute('aria-controls','properties-panel');}a.stage?.layout?.();}
export function setInspector(a,open){a.properties.flush();a.propertiesOpen=!!open;persist(a);syncWorkspace(a);}
export function toggleInspector(a){setInspector(a,!a.propertiesOpen);}
export function setGuidedWorkspace(a,guided){a.workspaceGuided=!!guided;a.showScaffold=true;a.shapesOpen=false;persist(a);syncWorkspace(a);a.render();}
export function showWorkspaceSettings(a){
 initWorkspace(a);const d=a.dialog('Workspace settings',`<fieldset class="workspace-mode-settings"><legend>Scaffold · guided workspace</legend><label class="workspace-switch"><input type="checkbox" data-guided ${a.workspaceGuided?'checked':''}> Scaffold on</label><p>On: fewer controls on the canvas, with relevant choices in Object options. Off: detailed controls stay visible in one compact row.</p><p class="subtle">Both modes keep every tool, selection outline and editing handle.</p></fieldset><fieldset><legend>Properties panel</legend><label class="workspace-switch"><input type="checkbox" data-inspector ${a.propertiesOpen?'checked':''}> Keep Properties open</label><p class="subtle">Use Properties beside the canvas to open or collapse this panel on any screen.</p></fieldset><p class="subtle">Workspace preferences are remembered on this device and do not change your artwork.</p><div class="dialog-actions"><button data-composition-settings>Composition settings</button><button data-close class="primary">Done</button></div>`);
 d.classList.add('workspace-settings-dialog');d.querySelector('[data-guided]').onchange=e=>setGuidedWorkspace(a,e.target.checked);d.querySelector('[data-inspector]').onchange=e=>setInspector(a,e.target.checked);d.querySelector('[data-composition-settings]').onclick=()=>{d.close();document.querySelector('#settings').click();};
}
// Mirror current controls into a popup without moving their IDs or event handlers.
export function controlCopies(ids){return ids.map(id=>{const source=document.getElementById(id);if(!source)return '';const copy=source.cloneNode(true);copy.removeAttribute('id');copy.removeAttribute('hidden');copy.setAttribute('data-workspace-control',id);copy.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));if(source.tagName==='SELECT')for(const option of copy.options)option.selected=option.value===source.value;if(source.tagName==='INPUT')copy.setAttribute('value',source.value);const name=source.getAttribute('aria-label')||source.getAttribute('title')||id.replaceAll('-',' ');return source.tagName==='SELECT'||source.tagName==='INPUT'?`<label>${name}${copy.outerHTML}</label>`:copy.outerHTML;}).join('');}
export function syncControlCopies(el,currentInput){for(const copy of el.querySelectorAll('[data-workspace-control]')){const source=document.getElementById(copy.dataset.workspaceControl);if(!source)continue;copy.disabled=!!source.disabled;copy.className=source.className;for(const name of ['aria-pressed','aria-expanded','aria-label','title']){const value=source.getAttribute(name);if(value!==null)copy.setAttribute(name,value);else copy.removeAttribute(name);}if(copy.tagName==='BUTTON'){if(copy.innerHTML!==source.innerHTML)copy.innerHTML=source.innerHTML;}else{if(copy.tagName==='SELECT'&&copy.innerHTML!==source.innerHTML)copy.innerHTML=source.innerHTML;if(copy!==currentInput)copy.value=source.value;}}}
export function bindControlCopies(a,el){
 const sync=()=>syncControlCopies(el,document.activeElement?.matches('input[data-workspace-control]')?document.activeElement:null);sync();
 el.addEventListener('click',e=>{const copy=e.target.closest('button[data-workspace-control]');if(!copy)return;const source=document.getElementById(copy.dataset.workspaceControl);if(source&&!source.disabled){const toggle=source.hasAttribute('aria-pressed');if(!toggle)el.closest('dialog')?.close();source.click();syncControlCopies(el);}});
 for(const event of ['input','change'])el.addEventListener(event,e=>{const copy=e.target.closest('input[data-workspace-control],select[data-workspace-control]');if(!copy)return;const source=document.getElementById(copy.dataset.workspaceControl);if(!source)return;source.value=copy.value;source.dispatchEvent(new Event(event,{bubbles:true}));syncControlCopies(el,event==='input'?copy:null);queueMicrotask(sync);});
 if(typeof MutationObserver!=='undefined'){let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;sync();});});for(const copy of el.querySelectorAll('[data-workspace-control]')){const source=document.getElementById(copy.dataset.workspaceControl);if(source)observer.observe(source,{attributes:true,attributeFilter:['disabled','class','aria-pressed','aria-expanded','aria-label','title'],childList:true,subtree:true});}el.closest('dialog')?.addEventListener('close',()=>observer.disconnect(),{once:true});}
}
export function showWorkspaceTools(a,kind='canvas'){
 const groups=kind==='blocks'?[['Sequencer tools',['timeline-touch-mode','block-selector','edit-block-tracks','split-block','copy-block','paste-block','trim-block','remove-block','block-start','block-end']]]:kind==='keys'?[['Keyframe tools',['snap-frames','add-key','sequence-editor','timeline-units','graph-editor','edit-key','copy-keys','paste-keys','delete-keys','easing','timeline-minus','timeline-plus']]]:[['Selection and movement',['multi','precision','snap','onion-skin','fit','zoom-out','zoom-in']],['Onion skin',['onion-count','onion-opacity']]];
 const d=a.dialog(kind==='blocks'?'Sequencer options':kind==='keys'?'Keyframe options':'Canvas options',groups.map(([title,ids])=>`<section><h3>${title}</h3><div class="workspace-option-grid">${controlCopies(ids)}</div></section>`).join(''));d.classList.add('workspace-options-dialog');bindControlCopies(a,d);
}
export function bindWorkspace(a){
 initWorkspace(a);document.querySelector('#workspace-settings')?.addEventListener('click',()=>showWorkspaceSettings(a));document.querySelector('#canvas-options')?.addEventListener('click',()=>showWorkspaceTools(a));document.querySelector('#block-options')?.addEventListener('click',()=>showWorkspaceTools(a,'blocks'));document.querySelector('#key-options')?.addEventListener('click',()=>showWorkspaceTools(a,'keys'));document.querySelector('#inspector-close')?.addEventListener('click',()=>setInspector(a,false));document.querySelector('#show-inspector')?.addEventListener('click',()=>setInspector(a,true));
 const inspector=document.querySelector('.inspector');if(inspector&&typeof MutationObserver!=='undefined'){a.workspaceInspectorObserver=new MutationObserver(()=>{const open=inspector.classList.contains('open');if(open!==a.propertiesOpen){a.propertiesOpen=open;persist(a);for(const button of document.querySelectorAll('[data-properties],#show-inspector'))button.setAttribute('aria-expanded',open);}});a.workspaceInspectorObserver.observe(inspector,{attributes:true,attributeFilter:['class']});}
}
